14	
15	import java.util.List;
16	import java.util.stream.Collectors;
17	
18	/**
19	 * 版块分类服务
20	 */
21	@Service
22	public class CategoryService {
23	
24	    private static final Logger logger = LoggerFactory.getLogger(CategoryService.class);
25	
26	    private final CategoryRepository categoryRepository;
27	    private final PostRepository postRepository;
28	
29	    public CategoryService(CategoryRepository categoryRepository, PostRepository postRepository) {
30	        this.categoryRepository = categoryRepository;
31	        this.postRepository = postRepository;
32	    }
33	
34	    /**
35	     * 获取所有版块（按排序顺序）
36	     */
37	    @Transactional(readOnly = true)
38	    public List<CategoryDTO> findAll() {
39	        return categoryRepository.findAllByOrderBySortOrderAsc()
40	                .stream()
41	                .map(this::toCategoryDTO)
42	                .collect(Collectors.toList());
43	    }
44	
45	    /**
46	     * 根据ID获取版块
47	     */
48	    @Transactional(readOnly = true)
49	    public CategoryDTO findById(Long id) {
50	        Category category = categoryRepository.findById(id)
51	                .orElseThrow(() -> new ResourceNotFoundException("版块不存在"));
52	        return toCategoryDTO(category);
53	    }
54	
55	    /**
56	     * 创建版块
57	     */
58	    @Transactional
59	    public CategoryDTO create(CreateCategoryRequest request) {
60	        // 检查名称是否重复
61	        if (categoryRepository.findByName(request.getName()).isPresent()) {
62	            throw new IllegalArgumentException("版块名称已存在");
63	        }
64	
65	        Category category = new Category(
66	                request.getName(),
67	                request.getDescription(),
68	                request.getSortOrder() != null ? request.getSortOrder() : 0
69	        );
70	        category = categoryRepository.save(category);
71	
72	        logger.info("版块创建成功: id={}, name={}", category.getId(), category.getName());
73	
74	        return toCategoryDTO(category);
75	    }
76	
77	    /**
78	     * 更新版块
79	     */
80	    @Transactional
81	    public CategoryDTO update(Long id, UpdateCategoryRequest request) {
82	        Category category = categoryRepository.findById(id)
83	                .orElseThrow(() -> new ResourceNotFoundException("版块不存在"));
84	
85	        // 如果修改名称，检查是否重复
86	        if (request.getName() != null && !request.getName().equals(category.getName())) {
87	            if (categoryRepository.findByName(request.getName()).isPresent()) {
88	                throw new IllegalArgumentException("版块名称已存在");
89	            }
90	            category.setName(request.getName());
91	        }
92	
93	        if (request.getDescription() != null) {
94	            category.setDescription(request.getDescription());
95	        }
96	
97	        if (request.getSortOrder() != null) {
98	            category.setSortOrder(request.getSortOrder());
99	        }
100	
101	        category = categoryRepository.save(category);
102	
103	        logger.info("版块更新成功: id={}, name={}", category.getId(), category.getName());
104	
105	        return toCategoryDTO(category);
106	    }
107	
108	    /**
109	     * 删除版块
110	     */
111	    @Transactional
112	    public void delete(Long id) {
113	        Category category = categoryRepository.findById(id)
114	                .orElseThrow(() -> new ResourceNotFoundException("版块不存在"));
115	
116	        // 检查是否有帖子引用此分类
117	        long postCount = postRepository.countByCategoryId(id);
118	        if (postCount > 0) {
119	            throw new IllegalStateException("该版块下还有 " + postCount + " 篇帖子，无法删除");
120	        }
121	
122	        categoryRepository.delete(category);
123	
124	        logger.info("版块删除成功: id={}, name={}", id, category.getName());
125	    }
126	
127	    /**
128	     * 转换为 CategoryDTO
129	     */
130	    private CategoryDTO toCategoryDTO(Category category) {
131	        return new CategoryDTO(
132	                category.getId(),
133	                category.getName(),
134	                category.getDescription(),
135	                category.getSortOrder(),
136	                category.getCreatedAt()
137	        );
138	    }
139	}
