1	package com.cc91.service;
2	
3	import com.cc91.dto.CategoryDTO;
4	import com.cc91.dto.CreateCategoryRequest;
5	import com.cc91.dto.UpdateCategoryRequest;
6	import com.cc91.entity.Category;
7	import com.cc91.exception.ResourceNotFoundException;
8	import com.cc91.repository.CategoryRepository;
9	import com.cc91.repository.PostRepository;
10	import org.slf4j.Logger;
11	import org.slf4j.LoggerFactory;
12	import org.springframework.stereotype.Service;
13	import org.springframework.transaction.annotation.Transactional;
14	
15	import java.time.LocalDate;
16	import java.time.LocalDateTime;
17	import java.util.List;
18	import java.util.stream.Collectors;
19	
20	/**
21	 * 版块分类服务
22	 */
23	@Service
24	public class CategoryService {
25	
26	    private static final Logger logger = LoggerFactory.getLogger(CategoryService.class);
27	
28	    private final CategoryRepository categoryRepository;
29	    private final PostRepository postRepository;
30	
31	    public CategoryService(CategoryRepository categoryRepository, PostRepository postRepository) {
32	        this.categoryRepository = categoryRepository;
33	        this.postRepository = postRepository;
34	    }
35	
36	    /**
37	     * 获取所有版块（按排序顺序）
38	     */
39	    @Transactional(readOnly = true)
40	    public List<CategoryDTO> findAll() {
41	        return categoryRepository.findAllByOrderBySortOrderAsc()
42	                .stream()
43	                .map(this::toCategoryDTO)
44	                .collect(Collectors.toList());
45	    }
46	
47	    /**
48	     * 根据ID获取版块
49	     */
50	    @Transactional(readOnly = true)
51	    public CategoryDTO findById(Long id) {
52	        Category category = categoryRepository.findById(id)
53	                .orElseThrow(() -> new ResourceNotFoundException("版块不存在"));
54	        return toCategoryDTO(category);
55	    }
56	
57	    /**
58	     * 创建版块
59	     */
60	    @Transactional
61	    public CategoryDTO create(CreateCategoryRequest request) {
62	        // 检查名称是否重复
63	        if (categoryRepository.findByName(request.getName()).isPresent()) {
64	            throw new IllegalArgumentException("版块名称已存在");
65	        }
66	
67	        Category category = new Category(
68	                request.getName(),
69	                request.getDescription(),
70	                request.getSortOrder() != null ? request.getSortOrder() : 0
71	        );
72	        category = categoryRepository.save(category);
73	
74	        logger.info("版块创建成功: id={}, name={}", category.getId(), category.getName());
75	
76	        return toCategoryDTO(category);
77	    }
78	
79	    /**
80	     * 更新版块
81	     */
82	    @Transactional
83	    public CategoryDTO update(Long id, UpdateCategoryRequest request) {
84	        Category category = categoryRepository.findById(id)
85	                .orElseThrow(() -> new ResourceNotFoundException("版块不存在"));
86	
87	        // 如果修改名称，检查是否重复
88	        if (request.getName() != null && !request.getName().equals(category.getName())) {
89	            if (categoryRepository.findByName(request.getName()).isPresent()) {
90	                throw new IllegalArgumentException("版块名称已存在");
91	            }
92	            category.setName(request.getName());
93	        }
94	
95	        if (request.getDescription() != null) {
96	            category.setDescription(request.getDescription());
97	        }
98	
99	        if (request.getSortOrder() != null) {
100	            category.setSortOrder(request.getSortOrder());
101	        }
102	
103	        category = categoryRepository.save(category);
104	
105	        logger.info("版块更新成功: id={}, name={}", category.getId(), category.getName());
106	
107	        return toCategoryDTO(category);
108	    }
109	
110	    /**
111	     * 删除版块
112	     */
113	    @Transactional
114	    public void delete(Long id) {
115	        Category category = categoryRepository.findById(id)
116	                .orElseThrow(() -> new ResourceNotFoundException("版块不存在"));
117	
118	        // 检查是否有帖子引用此分类
119	        long postCount = postRepository.countByCategoryId(id);
120	        if (postCount > 0) {
121	            throw new IllegalStateException("该版块下还有 " + postCount + " 篇帖子，无法删除");
122	        }
123	
124	        categoryRepository.delete(category);
125	
126	        logger.info("版块删除成功: id={}, name={}", id, category.getName());
127	    }
128	
129	    /**
130	     * 转换为 CategoryDTO
131	     */
132	    private CategoryDTO toCategoryDTO(Category category) {
133	        long postCount = postRepository.countByCategoryId(category.getId());
134	        LocalDateTime todayStart = LocalDate.now().atStartOfDay();
135	        long todayPostCount = postRepository.countByCategoryIdAndCreatedAtAfter(category.getId(), todayStart);
136	
137	        return new CategoryDTO(
138	                category.getId(),
139	                category.getName(),
140	                category.getDescription(),
141	                category.getSortOrder(),
142	                category.getCreatedAt(),
143	                postCount,
